-- Chỉ đọc: không chạy migration, không sửa dữ liệu/quyền.
DO $assert$
DECLARE missing text[];
BEGIN
 SELECT array_agg(label ORDER BY label) INTO missing
 FROM (VALUES
  ('sapo_customers.payment_days', (EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='sapo_customers' AND column_name='payment_days' AND data_type='integer' AND is_nullable='YES'))),
  ('sapo_customers.representative_contact_id', (EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='sapo_customers' AND column_name='representative_contact_id' AND data_type='text' AND is_nullable='YES'))),
  ('sapo_customers.reject_reason', (EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='sapo_customers' AND column_name='reject_reason' AND data_type='text' AND is_nullable='YES'))),
  ('sapo_customers.rejected_by', (EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='sapo_customers' AND column_name='rejected_by' AND data_type='text' AND is_nullable='YES'))),
  ('sapo_customers.rejected_at', (EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='sapo_customers' AND column_name='rejected_at' AND data_type='text' AND is_nullable='YES'))),
  ('FK representative SET NULL', (EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=to_regclass('public.sapo_customers') AND conname='fk_sapo_customers_representative' AND contype='f' AND convalidated AND strpos(pg_get_constraintdef(oid),'FOREIGN KEY (representative_contact_id) REFERENCES customer_contacts(id) ON DELETE SET NULL')>0))),
  ('FK rejected_by', (EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=to_regclass('public.sapo_customers') AND conname='fk_sapo_customers_rejected_by' AND contype='f' AND convalidated AND strpos(pg_get_constraintdef(oid),'FOREIGN KEY (rejected_by) REFERENCES staff_members(id)')>0))),
  ('payment_days CHECK', (EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=to_regclass('public.sapo_customers') AND conname='chk_customer_payment_days' AND contype='c' AND convalidated AND strpos(pg_get_constraintdef(oid),'payment_days IS NULL')>0 AND strpos(pg_get_constraintdef(oid),'payment_days >= 0')>0 AND strpos(pg_get_constraintdef(oid),'payment_days <= 3650')>0))),
  ('approval CHECK', (EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=to_regclass('public.sapo_customers') AND conname='chk_sapo_customers_approval' AND contype='c' AND convalidated AND strpos(pg_get_constraintdef(oid),'''pending''')>0 AND strpos(pg_get_constraintdef(oid),'''approved''')>0 AND strpos(pg_get_constraintdef(oid),'''rejected''')>0))),
  ('reject reason CHECK', (EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=to_regclass('public.sapo_customers') AND conname='chk_customer_reject_reason' AND contype='c' AND convalidated AND strpos(pg_get_constraintdef(oid),'reject_reason IS NOT NULL')>0 AND strpos(pg_get_constraintdef(oid),'btrim(reject_reason)')>0 AND strpos(pg_get_constraintdef(oid),'length(reject_reason) <= 1000')>0 AND strpos(pg_get_constraintdef(oid),'rejected_by IS NOT NULL')>0 AND strpos(pg_get_constraintdef(oid),'rejected_at IS NOT NULL')>0))),
  ('representative index', (EXISTS(SELECT 1 FROM pg_index i JOIN pg_class x ON x.oid=i.indexrelid JOIN pg_namespace n ON n.oid=x.relnamespace JOIN pg_am a ON a.oid=x.relam WHERE n.nspname='public' AND x.relname='idx_sapo_customers_representative' AND i.indrelid=to_regclass('public.sapo_customers') AND i.indisvalid AND i.indisready AND a.amname='btree' AND i.indnkeyatts=1 AND pg_get_indexdef(i.indexrelid,1,true)='representative_contact_id' AND pg_get_expr(i.indpred,i.indrelid)='(representative_contact_id IS NOT NULL)'))),
  ('customer_debt_notes', (EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('public.customer_debt_notes') AND relkind='r'))),
  ('customer_debt_notes.customer_id', (EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='customer_debt_notes' AND column_name='customer_id' AND data_type='text' AND is_nullable='NO'))),
  ('customer_debt_notes.text', (EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='customer_debt_notes' AND column_name='text' AND data_type='text' AND is_nullable='NO'))),
  ('customer_debt_notes.revision', (EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='customer_debt_notes' AND column_name='revision' AND data_type='bigint' AND is_nullable='NO'))),
  ('customer_debt_notes.updated_by', (EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='customer_debt_notes' AND column_name='updated_by' AND data_type='text' AND is_nullable='NO'))),
  ('customer_debt_notes.updated_at', (EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='customer_debt_notes' AND column_name='updated_at' AND data_type='text' AND is_nullable='NO'))),
  ('debt notes PK', (EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=to_regclass('public.customer_debt_notes') AND contype='p' AND convalidated AND pg_get_constraintdef(oid)='PRIMARY KEY (customer_id)'))),
  ('notes length CHECK', (EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=to_regclass('public.customer_debt_notes') AND conname='chk_customer_debt_notes_length' AND contype='c' AND convalidated AND strpos(pg_get_constraintdef(oid),'length(text) <= 2000')>0))),
  ('notes revision CHECK', (EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=to_regclass('public.customer_debt_notes') AND conname='chk_customer_debt_notes_revision' AND contype='c' AND convalidated AND strpos(pg_get_constraintdef(oid),'revision > 0')>0))),
  ('notes customer FK CASCADE', (EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=to_regclass('public.customer_debt_notes') AND conname='customer_debt_notes_customer_id_fkey' AND contype='f' AND convalidated AND strpos(pg_get_constraintdef(oid),'FOREIGN KEY (customer_id) REFERENCES sapo_customers(id) ON DELETE CASCADE')>0))),
  ('notes editor FK', (EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=to_regclass('public.customer_debt_notes') AND conname='customer_debt_notes_updated_by_fkey' AND contype='f' AND convalidated AND strpos(pg_get_constraintdef(oid),'FOREIGN KEY (updated_by) REFERENCES staff_members(id)')>0))),
  ('customer_debt_notes RLS', (EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('public.customer_debt_notes') AND relrowsecurity))),
  ('customer_debt_notes không cấp trực tiếp PUBLIC/anon/authenticated', (NOT EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) p LEFT JOIN pg_roles r ON r.oid=p.grantee WHERE c.oid=to_regclass('public.customer_debt_notes') AND (p.grantee=0 OR r.rolname IN ('anon','authenticated'))) AND NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname IN ('anon','authenticated') AND has_table_privilege(r.oid,to_regclass('public.customer_debt_notes'),'SELECT,INSERT,UPDATE,DELETE')))),
  ('customer_debt_notes quyền service_role', (NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname='service_role' AND NOT (has_table_privilege(r.oid,to_regclass('public.customer_debt_notes'),'SELECT') AND has_table_privilege(r.oid,to_regclass('public.customer_debt_notes'),'INSERT') AND has_table_privilege(r.oid,to_regclass('public.customer_debt_notes'),'UPDATE') AND has_table_privilege(r.oid,to_regclass('public.customer_debt_notes'),'DELETE') AND has_table_privilege(r.oid,to_regclass('public.customer_debt_notes'),'TRUNCATE') AND has_table_privilege(r.oid,to_regclass('public.customer_debt_notes'),'REFERENCES') AND has_table_privilege(r.oid,to_regclass('public.customer_debt_notes'),'TRIGGER')))))
 ) AS expected(label,ok) WHERE ok IS DISTINCT FROM true;
 IF coalesce(cardinality(missing),0)>0 THEN
  RAISE EXCEPTION 'Thiếu hoặc sai migration 20261111100000_customer_profile_fields.sql: %. Đối chiếu file và xin duyệt trước khi sửa DB.',array_to_string(missing,'; ');
 END IF;
END
$assert$;
SELECT 'customer_profile_fields_complete_ready' AS result;
